public class Solution {
    // De trás para frente: dp[w - p] ainda é da rodada anterior, então o item entra uma vez só.
    static long zeroUm(int[] peso, int[] valor, int W) {
        long[] dp = new long[W + 1];
        for (int i = 0; i < peso.length; i++)
            for (int w = W; w >= peso[i]; w--) dp[w] = Math.max(dp[w], dp[w - peso[i]] + valor[i]);
        return dp[W];
    }

    // Da frente para trás: dp[w - p] já pode conter o item, então ele pode repetir.
    static long ilimitada(int[] peso, int[] valor, int W) {
        long[] dp = new long[W + 1];
        for (int i = 0; i < peso.length; i++)
            for (int w = peso[i]; w <= W; w++) dp[w] = Math.max(dp[w], dp[w - peso[i]] + valor[i]);
        return dp[W];
    }
}

