import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

import java.util.*;

class SolutionTest {
    @Test void exemplo() {
        int[] p = {1, 3, 4, 5}, v = {1, 4, 5, 7};
        assertEquals(9, Solution.zeroUm(p, v, 7));
        assertEquals(9, Solution.ilimitada(p, v, 7));
        assertEquals(10, Solution.ilimitada(new int[]{2}, new int[]{5}, 4));
        assertEquals(5, Solution.zeroUm(new int[]{2}, new int[]{5}, 4));
    }

    @Test void aleatorioContraBruta() {
        var rnd = new Random(8);
        for (int t = 0; t < 200; t++) {
            int n = 1 + rnd.nextInt(8), W = rnd.nextInt(30);
            int[] p = rnd.ints(n, 1, 10).toArray(), v = rnd.ints(n, 0, 20).toArray();
            long melhor = 0;
            for (int m = 0; m < 1 << n; m++) {
                long sp = 0, sv = 0;
                for (int i = 0; i < n; i++) if ((m >> i & 1) == 1) { sp += p[i]; sv += v[i]; }
                if (sp <= W) melhor = Math.max(melhor, sv);
            }
            assertEquals(melhor, Solution.zeroUm(p, v, W));
        }
    }

    @Test void grande() {
        int n = 200, W = 100_000;
        int[] p = new int[n], v = new int[n];
        for (int i = 0; i < n; i++) { p[i] = 1000 + i; v[i] = 1_000_000_000; }
        assertTrue(Solution.zeroUm(p, v, W) > 0);
        assertEquals(100L * 1_000_000_000, Solution.ilimitada(p, v, W));
    }
}

