public class Solution {
    static int distancia(String a, String b) {
        int n = a.length(), m = b.length();
        int[] ant = new int[m + 1], cur = new int[m + 1];
        for (int j = 0; j <= m; j++) ant[j] = j; // base: inserir j caracteres
        for (int i = 1; i <= n; i++) {
            cur[0] = i;                           // base: remover i caracteres
            for (int j = 1; j <= m; j++) {
                if (a.charAt(i - 1) == b.charAt(j - 1)) cur[j] = ant[j - 1];
                else cur[j] = 1 + Math.min(ant[j - 1], Math.min(ant[j], cur[j - 1]));
            }
            int[] t = ant; ant = cur; cur = t;
        }
        return ant[m];
    }
}

