class SolutionTest {
    @Test void exemplos() {
        assertEquals(3, Solution.distancia("horse", "ros"));
        assertEquals(5, Solution.distancia("intention", "execution"));
    }

    @Test void bordas() {
        assertEquals(0, Solution.distancia("", ""));
        assertEquals(4, Solution.distancia("", "abcd"));
        assertEquals(3, Solution.distancia("abc", ""));
        assertEquals(0, Solution.distancia("igual", "igual"));
    }

    @Test void grande() {
        String a = "ab".repeat(1500), b = "ba".repeat(1500);
        assertEquals(2, Solution.distancia(a, b));
    }
}
